mapper.select:
with target_orders as (
    select distinct o.id
    from sale_orders o
    inner join sale_order_items i on i.sale_order_id = o.id
    left join rabbits r
      on r.id = i.rabbit_id
     and r.house_id = o.house_id
    where o.house_id = #{houseId}
      and (i.batch_id_snapshot = #{batchId}
           or (i.batch_id_snapshot is null
               and (r.birth_batch_id = #{batchId}
                    or exists (
                        select 1
                        from batch_rabbits historical_br
                        inner join batches historical_b
                          on historical_b.id = historical_br.batch_id
                         and historical_b.house_id = o.house_id
                        where historical_br.rabbit_id = i.rabbit_id
                          and historical_br.batch_id = #{batchId}
                          and historical_br.batch_role = 'fattening'
                    ))))
    union
    select distinct a0.sale_order_id
    from sale_order_batch_allocations a0
    where a0.house_id = #{houseId}
      and a0.batch_id = #{batchId}
)
select coalesce(sum(a.actual_weight_kg), 0) as soldWeightKg,
       coalesce(sum(a.amount), 0) as totalSalesAmount,
       case when coalesce(max(case when a.sale_order_id is null then 1 else 0 end), 0) = 1
           or exists (
               select 1
               from repro_events gap
               where gap.house_id = #{houseId}
                 and gap.batch_id = #{batchId}
                 and gap.target_type = 'BATCH'
                 and gap.target_id = #{batchId}
                 and gap.event_type = 'LEGACY_SALE_ALLOCATION_GAP'
           ) then 1 else 0 end as missingBatchSaleAllocation,
       case when coalesce(max(case when a.sale_order_id is not null
           and (a.unit_price_per_kg is null or a.amount is null) then 1 else 0 end), 0) = 1
           or exists (
               select 1
               from repro_events gap
               where gap.house_id = #{houseId}
                 and gap.batch_id = #{batchId}
                 and gap.target_type = 'BATCH'
                 and gap.target_id = #{batchId}
                 and gap.event_type = 'LEGACY_SALE_PRICE_GAP'
           ) then 1 else 0 end as missingSaleUnitPrice
from target_orders target
left join sale_order_batch_allocations a
  on a.sale_order_id = target.id
 and a.house_id = #{houseId}
 and a.batch_id = #{batchId}

select cy.yield_rate as carcassYieldRate
from batch_carcass_yield_versions cy
where cy.house_id = #{houseId}
  and cy.batch_id = #{batchId}
order by cy.created_at desc, cy.id desc
limit 1
